/** commonMain 没有 base64 解码，测试里只需要这一小段。 */
internal fun decodeBase64(value: String): ByteArray {
    val alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
    val output = ArrayList<Byte>(value.length * 3 / 4 + 3)
    var buffer = 0
    var bits = 0
    for (char in value) {
        if (char == '=' || char == '\n' || char == '\r' || char == ' ') continue
        val index = alphabet.indexOf(char)
        if (index < 0) continue
        buffer = (buffer shl 6) or index
        bits += 6
        if (bits >= 8) {
            bits -= 8
            output.add(((buffer shr bits) and 0xFF).toByte())
        }
    }
    return output.toByteArray()
}
